import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    public static final class AddressCommand {
        private final String street, city;
        public AddressCommand(String street, String city) { this.street = street; this.city = city; }
        public String getStreet() { return street; }
        public String getCity() { return city; }
    }

    public static final class NewProfileCommand {
        private final String name;
        private final int age;
        private final AddressCommand address;
        private final List<String> emails;
        public NewProfileCommand(String name, int age, AddressCommand address, List<String> emails) {
            this.name = name; this.age = age; this.address = address; this.emails = emails;
        }
        public String getName() { return name; }
        public int getAge() { return age; }
        public AddressCommand getAddress() { return address; }
        public List<String> getEmails() { return emails; }
    }

    public static final class Address {
        private final String street, city;
        private Address(String street, String city) { this.street = street; this.city = city; }
        public String getStreet() { return street; }
        public String getCity() { return city; }
    }

    public static final class Profile {
        private final String name;
        private final int age;
        private final Address address;
        private final List<String> emails;
        private Profile(String name, int age, Address address, List<String> emails) {
            this.name = name; this.age = age; this.address = address;
            this.emails = Collections.unmodifiableList(emails);
        }
        public String getName() { return name; }
        public int getAge() { return age; }
        public Address getAddress() { return address; }
        public List<String> getEmails() { return emails; }
    }

    public static Address mapAddress(AddressCommand command) {
        if (command == null) throw new IllegalArgumentException("Address is required");
        return new Address(command.getStreet(), command.getCity());
    }

    public static Profile mapProfile(NewProfileCommand command) {
        if (command == null || command.getAddress() == null || command.getEmails() == null
                || command.getEmails().contains(null)) {
            throw new IllegalArgumentException("Invalid profile command");
        }
        List<String> emails = new ArrayList<>(command.getEmails());
        return new Profile(command.getName(), command.getAge(), mapAddress(command.getAddress()), emails);
    }
}
